export function createCache({ ttlMs, capacity, clock = () => Date.now() }) {
  const entries = new Map() // key -> { value, expiresAt, lastUsed }
  // Recency is tracked by Map insertion order: reading or writing a key moves
  // it to the back, so the first entry in iteration order is the least
  // recently used. This stays correct even when the clock does not advance
  // between accesses.
  const touch = (key, entry, now) => {
    entries.delete(key)
    entry.lastUsed = now
    entries.set(key, entry)
  }
  return {
    get(key) {
      const entry = entries.get(key)
      if (entry === undefined) return undefined
      const now = clock()
      if (now > entry.expiresAt) {
        // TTL has passed: treat as a miss and drop the entry.
        entries.delete(key)
        return undefined
      }
      touch(key, entry, now)
      return entry.value
    },
    set(key, value) {
      const now = clock()
      if (entries.has(key)) {
        // Overwrite in place: refresh value, TTL and recency.
        entries.delete(key)
      } else if (entries.size >= capacity && entries.size > 0) {
        // Evict the least-recently-used entry (front of the Map).
        entries.delete(entries.keys().next().value)
      }
      entries.set(key, { value, expiresAt: now + ttlMs, lastUsed: now })
    },

